package dev.clientcompose

import kotlinx.serialization.KSerializer
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonElement

/** One of an action's declared errors: an outcome callers handle, such as a name that's taken. */
public interface DeclaredError {
    public val code: String
}

/**
 * One version of an action (spec §5). Generated by codegen from its manifest:
 *
 *     object RenameThingV1 : ActionDescriptor<RenameThingV1.Input, RenameThingV1.Result, RenameThingV1.Error> { … }
 *
 * Actions that declare no errors use `Nothing` for [E].
 */
public interface ActionDescriptor<I, R, E : DeclaredError> {
    public val action: String
    public val version: Int
    public val inputSerializer: KSerializer<I>
    public val resultSerializer: KSerializer<R>

    /** The codes this version declares. */
    public val errorCodes: List<String>

    /** The declared error for one of [errorCodes], decoding its details. */
    public fun decodeError(code: String, details: JsonElement?, json: Json): E

    /** An error's details as JSON, or null if it has none. */
    public fun encodeErrorDetails(error: E, json: Json): JsonElement?
}

/** How an action call ended, when the composer performed it. Anything else throws [ActionFailure]. */
public sealed interface ActionOutcome<out R, out E> {
    public data class Ok<out R>(val result: R, val effects: ActionEffects = ActionEffects()) : ActionOutcome<R, Nothing>

    public data class Error<out E>(val error: E) : ActionOutcome<Nothing, E>
}

/**
 * The composer didn't perform the action, or answered with something the app can't use: a protocol
 * error such as `unauthenticated` or `invalid_input`, a failure in front of the composer, or an
 * error code the action doesn't declare (spec §5.1). Show a generic message.
 */
public class ActionFailure(
    /** The HTTP status. */
    public val status: Int,
    /** The protocol error code, or the undeclared error code, if there is one. */
    public val code: String?,
    public val body: String,
) : RuntimeException("Action failed with status $status${code?.let { " ($it)" } ?: ""}")

/** A screen request failed (spec §4.3). [code] tells not found, unauthenticated and forbidden apart. */
public class ScreenException(
    /** The HTTP status. */
    public val status: Int,
    /** The protocol error code, e.g. "not_found", if the body has one. */
    public val code: String?,
    public val body: String,
) : RuntimeException("Screen request failed with status $status${code?.let { " ($it)" } ?: ""}") {
    public val isNotFound: Boolean get() = code == "not_found"
    public val isUnauthenticated: Boolean get() = code == "unauthenticated"
    public val isForbidden: Boolean get() = code == "forbidden"
}
